/// L5 state machine: the 7 named states from the atlas's F08-L5
/// `stateDiagram-v2`, in the fixed order `[*] -> PROBLEM_PROJECTED -> ... ->
/// RECEIPTED -> [*]`. `REFUSED` is deliberately NOT a variant here -- it is
/// the failure branch out of `DOMAIN_BOUND` and `PLANNING` (see
/// [`REFUSAL_SOURCES`]), modeled as `Err(Refusal)` at call sites rather
/// than folded into this success-state enum.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum PipelineState {
    ProblemProjected,
    DomainBound,
    ActionsBound,
    Planning,
    PlanFound,
    Validated,
    Receipted,
}

impl PipelineState {
    /// The atlas's own `SCREAMING_SNAKE_CASE` state name.
    #[must_use]
    pub const fn state_name(self) -> &'static str {
        match self {
            PipelineState::ProblemProjected => "PROBLEM_PROJECTED",
            PipelineState::DomainBound => "DOMAIN_BOUND",
            PipelineState::ActionsBound => "ACTIONS_BOUND",
            PipelineState::Planning => "PLANNING",
            PipelineState::PlanFound => "PLAN_FOUND",
            PipelineState::Validated => "VALIDATED",
            PipelineState::Receipted => "RECEIPTED",
        }
    }
}

impl std::fmt::Display for PipelineState {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.state_name())
    }
}

/// Lawful (non-refusal) transitions, `(from, to)`, straight from the
/// atlas's F08-L5 `stateDiagram-v2` edges labelled `lawful transition`.
pub const LAWFUL_TRANSITIONS: &[(PipelineState, PipelineState)] = &[
    (PipelineState::ProblemProjected, PipelineState::DomainBound),
    (PipelineState::DomainBound, PipelineState::ActionsBound),
    (PipelineState::ActionsBound, PipelineState::Planning),
    (PipelineState::Planning, PipelineState::PlanFound),
    (PipelineState::PlanFound, PipelineState::Validated),
    (PipelineState::Validated, PipelineState::Receipted),
];

/// States with an outgoing `REFUSED` edge in the atlas's F08-L5 diagram
/// (`DOMAIN_BOUND --> REFUSED: invalid`, `PLANNING --> REFUSED: authority
/// or conformance failure`). This is the *L5* (state-machine lens) cut;
/// F08-L2 (component-topology lens) names three refusal-attaching
/// components instead -- see `stage::refusal_stages()`. The pack ontology's
/// header comment discloses why these two lenses are not reconciled here.
pub const REFUSAL_SOURCES: &[PipelineState] =
    &[PipelineState::DomainBound, PipelineState::Planning];

/// Is `(from, to)` one of [`LAWFUL_TRANSITIONS`]?
///
/// # Complexity
/// O(n) linear scan over a fixed 6-entry table; not worth indexing.
#[must_use]
pub fn is_lawful_transition(from: PipelineState, to: PipelineState) -> bool {
    LAWFUL_TRANSITIONS
        .iter()
        .any(|&(f, t)| f == from && t == to)
}

